hudson.tasks.Shell.command:
#!/bin/bash # shellcheck disable=SC2154 # stack_s3_bucket is provided by Jenkins set -e
# Fails fast unless the data for the current deploy keys is already staged in the stack bucket # (both variants, plus data/<auth key>/fence_mapping.json). # Nothing is staged here: run HPDS Data - Stage to Stack Bucket (by hand) for a variant that is reported missing. # Outputs (read by the last SystemGroovy step, only when both variants are staged): # datasetKey.txt auth deploy key # destigmatizedDatasetKey.txt open deploy key # genomicDatasetKey.txt
rm -f datasetKey.txt destigmatizedDatasetKey.txt genomicDatasetKey.txt
# ---- shared with the other HPDS job (Check For Updates / HPDS Data - Stage to Stack Bucket): keep this block identical ---- dataset_marker="/data/hpds/pheno/datasets/"
# ListBucket on data/* is granted while HeadObject on a missing key may answer 403, so list first. key_exists() { local key="$1" out if out=$(aws s3api list-objects-v2 --bucket "${stack_s3_bucket}" --prefix "${key}" --output json 2> /dev/null); then # jq 1.6 -e exits 0 on empty input: an empty listing must mean "not there" [ -n "${out}" ] || return 1 printf '%s' "${out}" | jq -e --arg k "${key}" 'any(.Contents[]?; .Key == $k)' > /dev/null else aws s3api head-object --bucket "${stack_s3_bucket}" --key "${key}" > /dev/null 2>&1 fi }
# Commit that last changed the line of build-spec.json that holds the given field. # A boundary commit (root or shallow clone) is blamed as "^<hash>"; the marker is not part of the hash. blame_commit() { local key key=$(git blame --abbrev=39 build-spec.json | grep "$1" | cut -f 1 -d ' ') echo "${key#^}" }
# Deploy key = blame commit; must look like a git hash (7-40 hex) because it becomes an S3 key segment. deploy_key() { local key key=$(blame_commit "$1") if [ -z "${key}" ]; then echo "ERROR: no line for $1 in build-spec.json" >&2 exit 1 fi if ! [[ "${key}" =~ ^[0-9a-f]{7,40}$ ]]; then echo "ERROR: blame commit '${key}' for $1 is not a git hash" >&2 exit 1 fi echo "${key}" }
spec_url() { jq -r --arg f "$1" '.[$f] // ""' build-spec.json | tr -d '[:space:]' }
is_dataset_prefix() { case "$1" in *"${dataset_marker}"*) return 0 ;; esac return 1 }
# Dataset prefixes carry both variants in one dataset: the two URLs must be the same. require_identical_dataset_urls() { local auth_url open_url auth_url=$(spec_url source_dataset_s3_url) open_url=$(spec_url source_destigmatized_dataset_s3_url) if is_dataset_prefix "${auth_url}" || is_dataset_prefix "${open_url}"; then if [ "${auth_url}" != "${open_url}" ]; then echo "ERROR: source_dataset_s3_url (${auth_url}) and source_destigmatized_dataset_s3_url (${open_url}) must be identical for a dataset prefix" >&2 exit 1 fi fi }
# is_staged <deploy key> <stage prefix> <legacy tar name> # Staged = data/<key>/<stage prefix>manifest.tsv exists (per-file staging, written last) # or data/<key>/<legacy tar name>.tar exists (legacy .tar staging). is_staged() { key_exists "data/$1/$2manifest.tsv" || key_exists "data/$1/$3.tar" } # ---- end of shared block ----
require_identical_dataset_urls
# check_variant <variant> <build-spec field> <stage prefix> <legacy tar name> # Sets variant_key (deploy key) and variant_missing (true|false). check_variant() { local variant="$1" field="$2" stage_prefix="$3" legacy_name="$4" variant_key=$(deploy_key "${field}") if is_staged "${variant_key}" "${stage_prefix}" "${legacy_name}"; then variant_missing=false echo "${variant}: staged (deploy key ${variant_key})" else variant_missing=true fi }
check_variant auth source_dataset_s3_url javabins_rekeyed/ javabins_rekeyed auth_key="${variant_key}" auth_missing="${variant_missing}" check_variant open source_destigmatized_dataset_s3_url destigmatized_javabins_rekeyed/ destigmatized_javabins_rekeyed open_key="${variant_key}" open_missing="${variant_missing}"
if [ "${auth_missing}" = true ] || [ "${open_missing}" = true ]; then hint=auth if [ "${auth_missing}" = true ] && [ "${open_missing}" = true ]; then hint=both elif [ "${open_missing}" = true ]; then hint=open fi if [ "${auth_missing}" = true ]; then echo "ERROR: auth dataset is not staged: deploy key ${auth_key}, source $(spec_url source_dataset_s3_url); run HPDS Data - Stage to Stack Bucket with HPDS_VARIANT=${hint}" >&2 fi if [ "${open_missing}" = true ]; then echo "ERROR: open dataset is not staged: deploy key ${open_key}, source $(spec_url source_destigmatized_dataset_s3_url); run HPDS Data - Stage to Stack Bucket with HPDS_VARIANT=${hint}" >&2 fi echo "Nothing was scheduled." >&2 exit 1 fi
# The PSAMA deploy copies data/<auth key>/fence_mapping.json into its container, so "staged" also requires it. if ! key_exists "data/${auth_key}/fence_mapping.json"; then if key_exists "data/${auth_key}/javabins_rekeyed/manifest.tsv"; then echo "ERROR: auth dataset is staged but fence_mapping.json missing: deploy key ${auth_key} (data/${auth_key}/fence_mapping.json); run HPDS Data - Stage to Stack Bucket with HPDS_VARIANT=auth (restores it from the staged metadata.json)" >&2 else echo "ERROR: auth dataset is staged as a legacy tar but fence_mapping.json missing: deploy key ${auth_key} (data/${auth_key}/fence_mapping.json); it cannot be restored in place: restage under a new deploy key (commit a change to the source URL lines of build-spec.json, then run HPDS Data - Stage to Stack Bucket)" >&2 fi echo "Nothing was scheduled." >&2 exit 1 fi
echo "${auth_key}" > datasetKey.txt echo "${open_key}" > destigmatizedDatasetKey.txt blame_commit source_genomic_dataset_s3_url > genomicDatasetKey.txt

script.script:
import jenkins.*
import jenkins.model.*
import hudson.*
import hudson.model.*
import groovy.json.JsonSlurper;

def buildSpec = new JsonSlurper().parse(new File('/var/jenkins_home/workspace/Check For Updates/build-spec.json'));

def envVars= Hudson.instance.getItem("Check For Updates").lastBuild.properties.get("envVars");

Jenkins.instance.getItemByFullName("Bash_Functions")
.scheduleBuild2(0).get()


def run = Jenkins.instance.getItemByFullName("PIC-SURE Pipeline")
.scheduleBuild2(0).get()

if (run.getResult() != Result.SUCCESS) {
    throw new AbortException("PIC-SURE Pipeline failed")
}

import jenkins.*
import jenkins.model.*
import hudson.*
import hudson.model.*

def envVars= Hudson.instance.getItem("Check For Updates").lastBuild.properties.get("envVars");

// The shell step above failed the build unless both datasets are staged; it left the deploy keys in the workspace.
def readKey = { String fileName ->
    def keyFile = new File("/var/jenkins_home/workspace/Check For Updates/" + fileName)
    if (!keyFile.exists()) {
        throw new AbortException(fileName + " is missing: the staged check did not run or did not pass; Deployment Pipeline not started")
    }
    return keyFile.text.trim()
}

String dataset_s3_object_key = readKey("datasetKey.txt")
String destigmatized_dataset_s3_object_key = readKey("destigmatizedDatasetKey.txt")
String genomic_s3_object_key = readKey("genomicDatasetKey.txt")

Jenkins.instance.getItemByFullName("Deployment Pipeline")
    .scheduleBuild2(0, new ParametersAction([
        new StringParameterValue("deployment_git_hash", envVars["GIT_COMMIT"].trim()),
        new StringParameterValue("dataset_s3_object_key", dataset_s3_object_key),
        new StringParameterValue("destigmatized_dataset_s3_object_key", destigmatized_dataset_s3_object_key),
        new StringParameterValue("genomic_dataset_s3_object_key", genomic_s3_object_key),
])).get()
